            .DataType({ge::DT_BF16}).Format({ge::FORMAT_ND});
        this->Output("final_state").ParamType(REQUIRED)
            .DataType({ge::DT_FLOAT}).Format({ge::FORMAT_ND});
        this->AICore().SetTiling(optiling::TilingFunc).AddConfig("ascend910b");
