constexpr int32_t kVSplit = 2;                // blocks per head along the value axis
constexpr int32_t kRows = kDim / kVSplit;     // value rows per block
constexpr int32_t kTB = 16;                   // tokens per UB block
constexpr int32_t kPerTok = kHeads * kDim;    // elements per token in q/k/v/g
constexpr int32_t kPerTokBlocks = kPerTok / 8;
constexpr int32_t kStateElems = kDim * kRows;
constexpr float kNormEps = 1e-6f;

